import{_ as o,H as t,f as n,i as d}from"./chunks/framework.CBmkDW73.js";const p=JSON.parse('{"title":"design","description":"","frontmatter":{},"headers":[],"relativePath":"ko/skills/design.md","filePath":"ko/skills/design.md"}'),i={name:"ko/skills/design.md"};function s(a,e,r,c,l,g){return t(),n("div",null,[...e[0]||(e[0]=[d('<h1 id="design" tabindex="-1">design <a class="header-anchor" href="#design" aria-label="Permalink to &quot;design&quot;">​</a></h1><p><code>design</code> 스킬은 코딩이나 계획을 시작하기 전에 실행 가능한 명세를 작성합니다. 새로운 기능, 아키텍처 변경, 모호한 목표, 그리고 멀티 모듈 작업을 다룹니다.</p><h2 id="주요-기능" tabindex="-1">주요 기능 <a class="header-anchor" href="#주요-기능" aria-label="Permalink to &quot;주요 기능&quot;">​</a></h2><ol><li><strong>의존성 순서 명확화</strong>: 코드와 도구에서 확인할 수 있는 사실부터 먼저 해결하고, 사용자의 판단이 필요한 현재 결정 경계에 대해서만 순서대로 질문합니다.</li><li><strong>선언적 명세</strong>: 결정 사항을 선언적 계약(<code>contract:</code>, <code>invariant:</code>, <code>test:</code>, <code>convention:</code>, <code>deferred:</code>)으로 기록합니다.</li><li><strong>명세 리뷰어 게이트 (Spec Review Gate)</strong>: <code>plan</code>으로 전달하기 전 <a href="./reviewers.html">리뷰어 트리거 표</a>에 따라 명세를 점검하고 조건에 맞는 리뷰어를 병렬 서브에이전트로 실행합니다. Coordinator가 비판적 통합 평가를 거쳐 한 번에 명세를 수정합니다.</li><li><strong>멀티 모듈 토폴로지</strong>: 여러 리포지토리에 걸친 변경의 경우 Coordinator 리포지토리를 지정하고 디스크 상의 모드 마커(<code>topology: multi-module</code>)를 기록해 공유 명세와 모듈별 명세를 분리 관리합니다.</li><li><strong>중단 경로 (Abandon)</strong>: 탐색 결과 구현하지 않기로 결정되면 깔끔하게 중단하고, 산출된 지식은 <code>docs/decisions/</code>에 아카이브합니다.</li></ol>',4)])])}const h=o(i,[["render",s]]);export{p as __pageData,h as default};
